//          retrieved 2026-07-09. All stars with V mag <= 5.5 (RA converted hours->deg *15).
//   Deep-sky (Messier, NGC/IC): HYG DSO catalog (misc/dso.csv) - https://raw.githubusercontent.com/astronexus/HYG-Database/main/misc/dso.csv
//          retrieved 2026-07-09. Real J2000 positions, magnitudes, and morphological types.
//   M102 (disputed) identified with NGC 5866 per common convention.
// Deterministically parsed; no positions or magnitudes were invented.

export type ObjectType =
  | 'galaxy' | 'star' | 'open-cluster' | 'globular-cluster'
  | 'nebula' | 'planetary-nebula' | 'supernova-remnant' | 'double-star' | 'other';

export interface CatalogObject {
  id: string;
  name: string;
  ra: number;          // J2000 degrees, 0..360
  dec: number;         // J2000 degrees, -90..90
  type: ObjectType;
  magnitude: number;   // V mag (apparent)
  category: 'Bright Stars' | 'Messier' | 'NGC/IC' | 'Named Stars';
  spectralType?: string;
  description?: string;
}

// mk() gives each element the CatalogObject type directly, so the array's
// element type never balloons into a multi-thousand-member literal union
// (avoids TypeScript error TS2590 on a data file this large).
const mk = (o: CatalogObject): CatalogObject => o;

